	private static function write($action,$args){$slug=sanitize_key($args['slug']??'');if(!$slug)return new WP_Error('invalid_skill_slug','Skill slug is required.',array('status'=>400));if(isset(WPVDMCP_Skills::catalog()[$slug])||isset(self::extra_catalog()[$slug]))return new WP_Error('builtin_skill_immutable','Built-in skills cannot be changed by saved-skill tools.',array('status'=>409));$skills=self::saved();if('create'===$action&&isset($skills[$slug]))return new WP_Error('skill_exists','Saved skill already exists.',array('status'=>409));if(('update'===$action||'delete'===$action)&&!isset($skills[$slug]))return new WP_Error('skill_not_found','Saved skill not found.',array('status'=>404));$title=sanitize_text_field($args['title']??($skills[$slug]['title']??$slug));$description=sanitize_text_field($args['description']??($skills[$slug]['description']??''));if(strlen($description)>300)return new WP_Error('invalid_skill_description','Skill description must be at most 300 bytes.',array('status'=>400));$instructions=trim((string)($args['instructions']??($skills[$slug]['instructions']??'')));if('delete'!==$action&&(!$instructions||strlen($instructions)>self::MAX_BYTES))return new WP_Error('invalid_skill_instructions','Skill instructions are required and must be at most 20000 bytes.',array('status'=>400));$refs=array_key_exists('reference_files',$args)?self::sanitize_references($args['reference_files']):($skills[$slug]['reference_files']??array());if(is_wp_error($refs))return $refs;if('create'===$action&&count($skills)>=self::MAX_SKILLS)return new WP_Error('skill_limit','Saved skill limit reached.',array('status'=>409));$payload=array('action'=>$action,'slug'=>$slug,'title'=>$title,'description'=>$description,'instructions_hash'=>hash('sha256',$instructions),'references_hash'=>hash('sha256',wp_json_encode($refs)));$approval=self::approve($action.'_skill',$payload,$args);if(is_array($approval)||is_wp_error($approval))return $approval;if('delete'===$action){unset($skills[$slug]);update_option(self::OPTION,$skills,false);return array('status'=>'deleted','slug'=>$slug);}$record=array('slug'=>$slug,'title'=>$title,'description'=>$description,'min_wordpress'=>'6.0','min_wpvibe'=>'1.0.0','version'=>(int)($skills[$slug]['version']??0)+1,'instructions'=>$instructions,'reference_files'=>$refs);$skills[$slug]=$record;update_option(self::OPTION,$skills,false);return array('status'=>$action.'d','skill'=>$record);}
	private static function sanitize_references($refs){
		if(null===$refs)return array();if(!is_array($refs))return new WP_Error('invalid_skill_references','reference_files must be an array.',array('status'=>400));
		if(count($refs)>self::MAX_REFERENCE_FILES)return new WP_Error('skill_reference_limit','A saved skill can include at most 10 reference files.',array('status'=>400));
		$allowed=array('text/plain','text/markdown','text/csv','application/json');$out=array();
		foreach($refs as $ref){if(!is_array($ref))return new WP_Error('invalid_skill_reference','Each reference file must be an object.',array('status'=>400));$name=sanitize_file_name($ref['name']??'');$mime=sanitize_text_field($ref['mime_type']??'text/plain');$content=(string)($ref['content']??'');if(!$name||!in_array($mime,$allowed,true)||strlen($content)>self::MAX_REFERENCE_BYTES)return new WP_Error('invalid_skill_reference','Reference files require a safe text filename/MIME and at most 50000 bytes each.',array('status'=>400));$out[]=array('name'=>$name,'mime_type'=>$mime,'content'=>$content);}
		return $out;
