	private static function write_props($updating){return array('slug'=>self::strp('Saved skill slug.',true),'title'=>self::strp('Skill title.',!$updating),'description'=>self::strp('One-line description.'),'instructions'=>self::strp('Workflow instructions.',!$updating),'reference_files'=>array('type'=>'array','items'=>array('type'=>'object','properties'=>array('name'=>array('type'=>'string'),'mime_type'=>array('type'=>'string'),'content'=>array('type'=>'string')),'required'=>array('name','mime_type','content'),'additionalProperties'=>false),'description'=>'Up to 10 bounded text reference files.'),'approval_id'=>self::strp('One-time approval ID.'));}
